import{_ as i,D as c,o as d,c as n,j as e,a,I as t,w as r,am as l}from"./chunks/framework.DXw8qDd0.js";const k=JSON.parse('{"title":"安装mcp","description":"","frontmatter":{"title":"安装mcp","time":"2026-06-07T00:00:00.000Z","tags":["codex"]},"headers":[],"relativePath":"笔记/Codex/安装mcp.md","filePath":"笔记/Codex/安装mcp.md"}'),h={name:"笔记/Codex/安装mcp.md"},s=l('<h1 id="codex-mcp-服务安装与配置指南" tabindex="-1">Codex MCP 服务安装与配置指南 <a class="header-anchor" href="#codex-mcp-服务安装与配置指南" aria-label="Permalink to &quot;Codex MCP 服务安装与配置指南&quot;">​</a></h1><blockquote><p>本文档记录如何为 Codex 安装和配置 MCP（Model Context Protocol）服务，扩展 AI Agent 的能力边界。</p></blockquote><hr><h2 id="一、配置文件说明" tabindex="-1">一、配置文件说明 <a class="header-anchor" href="#一、配置文件说明" aria-label="Permalink to &quot;一、配置文件说明&quot;">​</a></h2><p>MCP 的配置文件格式为 config.toml，用于声明已安装的 MCP 服务及其连接参数。</p><hr><h2 id="二、安装常用-mcp-服务" tabindex="-1">二、安装常用 MCP 服务 <a class="header-anchor" href="#二、安装常用-mcp-服务" aria-label="Permalink to &quot;二、安装常用 MCP 服务&quot;">​</a></h2><h3 id="_1-draw-io-mcp" tabindex="-1">1. Draw.io MCP <a class="header-anchor" href="#_1-draw-io-mcp" aria-label="Permalink to &quot;1. Draw.io MCP&quot;">​</a></h3><p>用于在 Codex 中绘制和编辑流程图、架构图等可视化图表。</p>',9),p=e("strong",null,"仓库地址",-1),_=e("li",null,[e("strong",null,"安装命令"),a("：")],-1),m=l('<p><code>\bash codex mcp add drawio npx @anthropic-ai/drawio-mcp@latest </code></p><h3 id="_2-playwright-mcp" tabindex="-1">2. Playwright MCP <a class="header-anchor" href="#_2-playwright-mcp" aria-label="Permalink to &quot;2. Playwright MCP&quot;">​</a></h3><p>为 Codex 提供浏览器自动化能力，可在 Headless 模式下访问网页、截图、交互等。</p><ul><li><strong>安装命令</strong>：</li></ul><p><code>\bash codex mcp add playwright npx @playwright/mcp@latest </code></p><blockquote><p><strong>什么是 Headless 模式？</strong> Playwright 在 Headless 模式下启动 Chromium 浏览器——浏览器像「隐身模式」一样在后台默默工作，没有可见窗口，但所有网页功能都正常运行。</p></blockquote><hr><h2 id="三、查看已安装的-mcp-服务" tabindex="-1">三、查看已安装的 MCP 服务 <a class="header-anchor" href="#三、查看已安装的-mcp-服务" aria-label="Permalink to &quot;三、查看已安装的 MCP 服务&quot;">​</a></h2><p>进入 Codex 后，使用 /mcp 命令可以列出当前已安装的所有 MCP 服务列表，确认安装是否成功。</p><hr><h2 id="四、相关插件" tabindex="-1">四、相关插件 <a class="header-anchor" href="#四、相关插件" aria-label="Permalink to &quot;四、相关插件&quot;">​</a></h2><ul><li><strong>HyperFrames</strong> — 视频创作与动画插件，支持在 Codex 中构建 HTML 视频合成、GSAP 动画、字幕配音等。</li></ul><hr><h2 id="五、关联连接" tabindex="-1">五、关联连接 <a class="header-anchor" href="#五、关联连接" aria-label="Permalink to &quot;五、关联连接&quot;">​</a></h2><ul><li>[[LLM_Wiki_Methodology]] — LLM Wiki 方法论，本文所属的知识体系</li><li>[[Codex_Platform]] — Codex 平台介绍（待创建）</li></ul><hr><hr>',17);function u(P,C,x,b,g,f){const o=c("VPNolebaseInlineLinkPreview");return d(),n("div",null,[s,e("ul",null,[e("li",null,[p,a("："),t(o,{href:"https://github.com/jgraph/drawio-mcp",target:"_blank",rel:"noreferrer"},{default:r(()=>[a("https://github.com/jgraph/drawio-mcp")]),_:1})]),_]),m,e("blockquote",null,[e("p",null,[a("📎 "),t(o,{href:"/ocdsync/笔记/"},{default:r(()=>[a("📒 返回笔记索引")]),_:1})])])])}const w=i(h,[["render",u]]);export{k as __pageData,w as default};
